CREATE TABLE IF NOT EXISTS sites (site_id TEXT NOT NULL PRIMARY KEY, site_name TEXT NOT NULL, site_type TEXT, registered_population INTEGER CHECK (registered_population IS NULL OR (typeof(registered_population) IN ('integer') AND registered_population >= 0 AND registered_population <= 1.7976931348623157e308)), meal_capacity INTEGER CHECK (meal_capacity IS NULL OR (typeof(meal_capacity) IN ('integer') AND meal_capacity >= 0 AND meal_capacity <= 1.7976931348623157e308)), created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE IF NOT EXISTS predictions (prediction_id TEXT NOT NULL PRIMARY KEY, site_id TEXT NOT NULL, target_date TEXT NOT NULL, predicted_diners REAL NOT NULL CHECK (predicted_diners IS NULL OR (typeof(predicted_diners) IN ('integer','real') AND predicted_diners >= 0 AND predicted_diners <= 1.7976931348623157e308)), lower_bound REAL CHECK (lower_bound IS NULL OR (typeof(lower_bound) IN ('integer','real') AND lower_bound >= 0 AND lower_bound <= 1.7976931348623157e308)), upper_bound REAL CHECK (upper_bound IS NULL OR (typeof(upper_bound) IN ('integer','real') AND upper_bound >= 0 AND upper_bound <= 1.7976931348623157e308)), predicted_rate REAL CHECK (predicted_rate IS NULL OR (typeof(predicted_rate) IN ('integer','real') AND predicted_rate >= 0 AND predicted_rate <= 1.7976931348623157e308)), available_population REAL CHECK (available_population IS NULL OR (typeof(available_population) IN ('integer','real') AND available_population >= 0 AND available_population <= 1.7976931348623157e308)), model_version TEXT, model_type TEXT, applicability TEXT, confidence TEXT, created_at TEXT NOT NULL, request_id TEXT, input_snapshot_json TEXT, FOREIGN KEY(site_id) REFERENCES sites(site_id), UNIQUE(request_id), UNIQUE(prediction_id, site_id, target_date), CHECK(lower_bound IS NULL OR upper_bound IS NULL OR lower_bound <= upper_bound));
CREATE TABLE IF NOT EXISTS operation_plans (plan_id TEXT NOT NULL PRIMARY KEY, prediction_id TEXT NOT NULL, site_id TEXT NOT NULL, target_date TEXT NOT NULL, recommended_servings INTEGER NOT NULL CHECK (recommended_servings IS NULL OR (typeof(recommended_servings) IN ('integer') AND recommended_servings >= 0 AND recommended_servings <= 1.7976931348623157e308)), base_demand REAL CHECK (base_demand IS NULL OR (typeof(base_demand) IN ('integer','real') AND base_demand >= 0 AND base_demand <= 1.7976931348623157e308)), safety_margin REAL CHECK (safety_margin IS NULL OR (typeof(safety_margin) IN ('integer','real') AND safety_margin >= 0 AND safety_margin <= 1.7976931348623157e308)), status TEXT, ingredient_requirements_json TEXT, order_reviews_json TEXT, alerts_json TEXT, constraints_json TEXT, requires_human_approval INTEGER NOT NULL DEFAULT 1 CHECK (requires_human_approval IS NULL OR requires_human_approval IN (0,1)), created_at TEXT NOT NULL, FOREIGN KEY(site_id) REFERENCES sites(site_id), FOREIGN KEY(prediction_id, site_id, target_date) REFERENCES predictions(prediction_id, site_id, target_date));
CREATE TABLE IF NOT EXISTS actual_results (result_id TEXT NOT NULL PRIMARY KEY, site_id TEXT NOT NULL, target_date TEXT NOT NULL, actual_diners INTEGER NOT NULL CHECK (actual_diners IS NULL OR (typeof(actual_diners) IN ('integer') AND actual_diners >= 0 AND actual_diners <= 1.7976931348623157e308)), prepared_servings INTEGER CHECK (prepared_servings IS NULL OR (typeof(prepared_servings) IN ('integer') AND prepared_servings >= 0 AND prepared_servings <= 1.7976931348623157e308)), unserved_leftover_kg REAL CHECK (unserved_leftover_kg IS NULL OR (typeof(unserved_leftover_kg) IN ('integer','real') AND unserved_leftover_kg >= 0 AND unserved_leftover_kg <= 1.7976931348623157e308)), plate_waste_kg REAL CHECK (plate_waste_kg IS NULL OR (typeof(plate_waste_kg) IN ('integer','real') AND plate_waste_kg >= 0 AND plate_waste_kg <= 1.7976931348623157e308)), ingredient_waste_kg REAL CHECK (ingredient_waste_kg IS NULL OR (typeof(ingredient_waste_kg) IN ('integer','real') AND ingredient_waste_kg >= 0 AND ingredient_waste_kg <= 1.7976931348623157e308)), shortage INTEGER NOT NULL DEFAULT 0 CHECK (shortage IS NULL OR shortage IN (0,1)), actual_food_cost REAL CHECK (actual_food_cost IS NULL OR (typeof(actual_food_cost) IN ('integer','real') AND actual_food_cost >= 0 AND actual_food_cost <= 1.7976931348623157e308)), notes TEXT, created_at TEXT NOT NULL, updated_at TEXT, FOREIGN KEY(site_id) REFERENCES sites(site_id), UNIQUE(site_id, target_date));
CREATE TABLE IF NOT EXISTS inventory_snapshots (inventory_id TEXT NOT NULL PRIMARY KEY, site_id TEXT NOT NULL, snapshot_date TEXT NOT NULL, ingredient_name TEXT NOT NULL, normalized_ingredient_name TEXT, quantity REAL NOT NULL CHECK (quantity IS NULL OR (typeof(quantity) IN ('integer','real') AND quantity >= 0 AND quantity <= 1.7976931348623157e308)), unit TEXT NOT NULL, expiry_date TEXT, lot_id TEXT, source TEXT, created_at TEXT NOT NULL, FOREIGN KEY(site_id) REFERENCES sites(site_id));
CREATE TABLE IF NOT EXISTS model_versions (model_version TEXT NOT NULL PRIMARY KEY, model_type TEXT NOT NULL, trained_at TEXT, training_rows INTEGER CHECK (training_rows IS NULL OR (typeof(training_rows) IN ('integer') AND training_rows >= 0 AND training_rows <= 1.7976931348623157e308)), validation_rows INTEGER CHECK (validation_rows IS NULL OR (typeof(validation_rows) IN ('integer') AND validation_rows >= 0 AND validation_rows <= 1.7976931348623157e308)), validation_mae REAL CHECK (validation_mae IS NULL OR (typeof(validation_mae) IN ('integer','real') AND validation_mae >= 0 AND validation_mae <= 1.7976931348623157e308)), validation_rmse REAL CHECK (validation_rmse IS NULL OR (typeof(validation_rmse) IN ('integer','real') AND validation_rmse >= 0 AND validation_rmse <= 1.7976931348623157e308)), validation_mape REAL CHECK (validation_mape IS NULL OR (typeof(validation_mape) IN ('integer','real') AND validation_mape >= 0 AND validation_mape <= 1.7976931348623157e308)), status TEXT, parent_version TEXT, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_logs (decision_id TEXT NOT NULL PRIMARY KEY, site_id TEXT NOT NULL, target_date TEXT NOT NULL, decision_type TEXT, recommendation_json TEXT, critical_alerts_json TEXT, confidence TEXT, requires_human_approval INTEGER NOT NULL DEFAULT 1 CHECK (requires_human_approval IS NULL OR requires_human_approval IN (0,1)), approved INTEGER CHECK (approved IS NULL OR approved IN (0,1)), approved_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(site_id) REFERENCES sites(site_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_current_model ON model_versions(status) WHERE status = 'current';
CREATE INDEX IF NOT EXISTS ix_predictions ON predictions(site_id,target_date);
CREATE INDEX IF NOT EXISTS ix_operation_plans ON operation_plans(prediction_id,created_at);
CREATE INDEX IF NOT EXISTS ix_inventory_snapshots ON inventory_snapshots(site_id,snapshot_date);
CREATE INDEX IF NOT EXISTS ix_decision_logs ON decision_logs(site_id,target_date);
PRAGMA user_version=1;
